#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const sourceDir = path.join(root, 'content', 'localization', 'en');
const output = path.join(root, 'src', 'literary-localization-bundle.js');
const files = fs.readdirSync(sourceDir)
  .filter(file => /^S\d{2}\.json$/u.test(file))
  .sort((a, b) => Number(a.slice(1, 3)) - Number(b.slice(1, 3)));

if (!files.length) throw new Error('EN_LOCALIZATION_CORPUS_EMPTY');

const scenes = {};
for (const file of files) {
  const data = JSON.parse(fs.readFileSync(path.join(sourceDir, file), 'utf8'));
  if (data.locale !== 'en') throw new Error(`INVALID_EN_LOCALE:${file}`);
  for (const [sceneId, scene] of Object.entries(data.scenes ?? {})) {
    if (scenes[sceneId]) throw new Error(`DUPLICATE_EN_SCENE:${sceneId}`);
    scenes[sceneId] = scene;
  }
}

const interactionFile = path.join(sourceDir, 'interaction-beats.json');
const interactionData = JSON.parse(fs.readFileSync(interactionFile, 'utf8'));
if (interactionData.locale !== 'en') throw new Error('INVALID_EN_INTERACTION_LOCALE');
const bundle = { en: { schemaVersion: 1, locale: 'en', scenes, interactionBeats: interactionData.interactionBeats, interactionEchoes: interactionData.interactionEchoes } };
fs.writeFileSync(
  output,
  `// GENERATED by tools/literary/build-locale-bundle.mjs. Do not edit this file.\nexport const literaryLocaleBundles = ${JSON.stringify(bundle, null, 2)};\n`,
  'utf8'
);
console.log(`LITERARY_LOCALE_BUNDLE_OK ${files.length} files ${Object.keys(scenes).length} scenes`);
